render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(group = cfg$x, before = cfg$y, after = cfg$group), c("group", "before", "after")); long <- rbind(data.frame(group = data[[cfg$x]], series = "第一组", value = data[[cfg$y]]), data.frame(group = data[[cfg$x]], series = "第二组", value = data[[cfg$group]])); p <- ggplot2::ggplot(long, ggplot2::aes(x = value, y = group, colour = series)) + ggplot2::geom_line(ggplot2::aes(group = group), colour = "#CBD5E1") + ggplot2::geom_point(size = 3) + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = "数值", y = NULL, colour = "组别"); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
